/* ---- runtime ------------------------------------------------------------ */
function detectLang() {
  const stored = localStorage.getItem("seam_lang");
  if (stored && I18N[stored]) return stored;
  const nav = (navigator.language || "bg").slice(0, 2).toLowerCase();
  return I18N[nav] ? nav : "bg";
}
function writeLangCookie(code) {
  try { document.cookie = "seam_lang=" + code + ";path=/;max-age=31536000;samesite=lax"; } catch (e) {}
}
let LANG = detectLang();
writeLangCookie(LANG); // so the very first API calls return demo content in this language

function setLang(code) {
  if (!I18N[code]) return;
  LANG = code;
  localStorage.setItem("seam_lang", code);
  writeLangCookie(code);
  document.documentElement.lang = code;
  if (typeof render === "function") render();
}

/* Counting, in languages that inflect the thing being counted.
 *
 * Every string carrying {n} used to be written once and interpolated blindly,
 * so a Bulgarian screen said "1 дни", a Russian one "1 дней" and an English
 * one "1 days". A count next to a noun is not a fill-in-the-blank.
 *
 * A translation may now carry its forms separated by a vertical bar, and the
 * rule below picks one. Values without a bar behave exactly as before, so
 * nothing that does not count is affected.
 *
 * The rules are CLDR's. Bulgarian, Greek, German, Turkish and the Romance
 * languages need two forms; Russian, Ukrainian and Polish need three; Romanian
 * needs three on a different boundary.
 */
function pluralIndex(lang, n) {
  const i = Math.abs(Number(n));
  if (!isFinite(i)) return 0;
  const mod10 = i % 10, mod100 = i % 100;
  switch (lang) {
    case "ru":
    case "uk":
      if (mod10 === 1 && mod100 !== 11) return 0;
      if (mod10 >= 2 && mod10 <= 4 && (mod100 < 12 || mod100 > 14)) return 1;
      return 2;
    case "pl":
      if (i === 1) return 0;
      if (mod10 >= 2 && mod10 <= 4 && (mod100 < 12 || mod100 > 14)) return 1;
      return 2;
    case "ro":
      if (i === 1) return 0;
      // Romanian takes the "few" form for zero and for anything ending 01..19.
      if (i === 0 || (mod100 >= 1 && mod100 <= 19)) return 1;
      return 2;
    case "fr":
      return i < 2 ? 0 : 1;          // French counts 0 as singular
    default:
      return i === 1 ? 0 : 1;
  }
}

function t(key, vars) {
  const dict = (I18N[LANG] && I18N[LANG].ui) || {};
  let s = dict[key];
  if (s === undefined) s = (I18N.en.ui[key] !== undefined ? I18N.en.ui[key] : key);
  if (s.indexOf("|") !== -1 && vars && vars.n !== undefined) {
    const forms = s.split("|");
    // A translation with fewer forms than the rule asks for falls back to its
    // last one rather than to undefined.
    s = forms[Math.min(pluralIndex(LANG, vars.n), forms.length - 1)];
  }
  if (vars) for (const k in vars) s = s.replace(new RegExp("\\{" + k + "\\}", "g"), vars[k]);
  return s;
}

function _tplBlock(tplKey) {
  return (I18N[LANG].tpl && I18N[LANG].tpl[tplKey]) || (I18N.en.tpl && I18N.en.tpl[tplKey]) || null;
}
function tplLabel(tplKey, fb) { const b = _tplBlock(tplKey); return (b && b.label) || fb || tplKey; }
function tplTagline(tplKey, fb) { const b = _tplBlock(tplKey); return (b && b.tagline) || fb || ""; }
function tplNoun(tplKey, fb) { const b = _tplBlock(tplKey); return (b && b.noun) || fb || ""; }
/* Quoting a person's own words - an approval note, a rejection reason - in the
   reader's own punctuation. The marks were hardcoded German, and mismatched at
   that: „…" opened one way and closed another. */
function quoted(text) { return t("quote_open") + text + t("quote_close"); }

/* Add-on strings live in their own block, not repeated inside every template
   they apply to. "Задържана гаранция" is the same phrase whether it arrives
   through the construction template or the general one, and writing it once
   per language is the difference between 130 strings and 900. */
function _addonBlocks() {
  return [I18N[LANG] && I18N[LANG].addon, I18N.en.addon].filter(Boolean);
}
function _addonPart(part, key) {
  for (const blocks of _addonBlocks()) {
    for (const a in blocks) {
      const got = blocks[a][part] && blocks[a][part][key];
      if (got) return got;
    }
  }
  return null;
}
function tplMetric(key, fb) { return _addonPart("metrics", key) || fb || key; }
function addonLabel(key, fb) {
  for (const b of _addonBlocks()) if (b[key] && b[key].label) return b[key].label;
  return fb || key;
}
function addonTagline(key, fb) {
  for (const b of _addonBlocks()) if (b[key] && b[key].tagline) return b[key].tagline;
  return fb || "";
}

function tplStage(tplKey, stageKey, fb) {
  const b = _tplBlock(tplKey);
  return (b && b.stages && b.stages[stageKey]) || _addonPart("stages", stageKey) || fb || stageKey;
}
function tplField(tplKey, fieldKey, fb) {
  const b = _tplBlock(tplKey);
  return (b && b.fields && b.fields[fieldKey]) || _addonPart("fields", fieldKey) || fb || fieldKey;
}

document.documentElement.lang = LANG;
